<?php
declare(strict_types=1);
$email=mb_strtolower(trim((string)($argv[1]??'')));if(filter_var($email,FILTER_VALIDATE_EMAIL)===false||preg_match('/^[^@]+@shlz\.ru$/D',$email)!==1)throw new InvalidArgumentException('Usage: php rapid-pilot/issue-invitation.php name@shlz.ru');
$home=getenv('HOME');if(!is_string($home)||$home==='')throw new RuntimeException('Home unavailable');$root=dirname(__DIR__);$fingerprint=substr(hash('sha256',(string)realpath($root)),0,8);$manifest=json_decode((string)file_get_contents($home.'/.local/state/fmonitor2/pilot-demo/'.$fingerprint.'/active.json'),true,flags:JSON_THROW_ON_ERROR);$p=(string)($manifest['processPrefix']??'');if(preg_match('/^[A-Za-z0-9_]+$/D',$p)!==1)throw new RuntimeException('Pilot generation unavailable');
$db=new mysqli(getenv('FMONITOR_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_DB_USER')?:'fmonitor2_demo',getenv('FMONITOR_DB_PASSWORD')?:'fmonitor2_demo_local',getenv('FMONITOR_DB_NAME')?:'fmonitor2_demo',(int)(getenv('FMONITOR_DB_PORT')?:'23306'));$db->set_charset('utf8mb4');$db->begin_transaction();try{$s=$db->prepare("SELECT user_id,status,activation_state FROM `{$p}fm2_pilot_users` WHERE email=? FOR UPDATE");$s->bind_param('s',$email);$s->execute();$user=$s->get_result()->fetch_assoc();if(!is_array($user)||(int)$user['status']!==1||$user['activation_state']!=='invited')throw new RuntimeException('Invited active user not found');$userId=(int)$user['user_id'];$db->query("UPDATE `{$p}fm2_pilot_invitations` SET revoked_at=NOW(6) WHERE user_id={$userId} AND used_at IS NULL AND revoked_at IS NULL");$token=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$hash=hash('sha256',$token,true);$i=$db->prepare("INSERT INTO `{$p}fm2_pilot_invitations`(user_id,token_hash,expires_at,created_by_user_id,created_at) VALUES(?,?,DATE_ADD(NOW(6),INTERVAL 24 HOUR),NULL,NOW(6))");$i->bind_param('is',$userId,$hash);$i->execute();$db->commit();echo "/pilot/activate?token={$token}\n";}catch(Throwable$e){$db->rollback();throw$e;}finally{$db->close();}
